/// <summary>
///     AVA <c>initComponentwithBaseSalesLine</c> method.
/// </summary>
/// <param name="sender">
///     <c>FormControl</c> as type
/// </param>
/// <param name="e">
///     <c>FormControlEventArgs</c> as type
/// </param>
[FormControlEventHandler(formControlStr(InventTransferOrders, LineViewHeader_InventLocationIdTo), FormControlEventType::Lookup)]
public static void LineViewHeader_InventLocationIdTo_OnLookup(FormControl sender, FormControlEventArgs e)
{
    FormControlCancelableSuperEventArgs ce;

    AVAInventTransferOrdersFrm_EventHandler::lookupInventLocationAll(sender);

    ce = e as FormControlCancelableSuperEventArgs;

    ce.CancelSuperCall();
}

/// <summary>
///     AVA <c>initComponentwithBaseSalesLine</c> method.
/// </summary>
/// <param name="sender">
///     <c>FormControl</c> as type
/// </param>
/// <param name="e">
///     <c>FormControlEventArgs</c> as type
/// </param>
[FormControlEventHandler(formControlStr(InventTransferOrders, LineViewHeader_InventLocationIdFrom), FormControlEventType::Lookup)]
public static void LineViewHeader_InventLocationIdFrom_OnLookup(FormControl sender, FormControlEventArgs e)
{
    FormControlCancelableSuperEventArgs ce;

    AVAInventTransferOrdersFrm_EventHandler::lookupInventLocationAll(sender);

    ce = e as FormControlCancelableSuperEventArgs;

    ce.CancelSuperCall();
}

/// <summary>
///     AVA <c>lookupInventLocation</c> method.
/// </summary>
/// <param name="_ctrl">
///     <c>FormStringControl</c> as type
/// </param>
public static void lookupInventLocationAll(FormStringControl _ctrl)
{
    SysTableLookup          locSysTableLookup = SysTableLookup::newParameters(tableNum(InventLocation), _ctrl);
    Query                   locQuery;
    QueryBuildDataSource    locQueryBuildDataSource;
    QueryBuildRange         locQueryBuildRange;

    locQuery = new Query();

    locSysTableLookup.addLookupfield(fieldNum(InventLocation, InventLocationId));
    locSysTableLookup.addLookupfield(fieldNum(InventLocation, Name));
    locSysTableLookup.addLookupfield(fieldNum(InventLocation, InventSiteId));

    locQueryBuildDataSource = locQuery.addDataSource(tableNum(InventLocation));

    //locQueryBuildRange = locQueryBuildDataSource.addRange(fieldNum(InventLocation, InventLocationType));
    //locQueryBuildRange.value(SysQuery::valueNot(InventLocationType::Quarantine));
    locSysTableLookup.parmQuery(locQuery);
    locSysTableLookup.performFormLookup();
}
